mapper.select:
select

from t_data_attachment_operation_log l


        AND l.user_id IN

            #{item}



        AND l.phone = #{inputDto.phone}


        AND LOWER(l.real_name) LIKE LOWER(CONCAT('%', #{inputDto.realName}, '%'))


        AND l.operate_source = #{inputDto.operateSource}


        AND l.module = #{inputDto.module}


        AND l.module_entity = #{inputDto.moduleEntity}


        AND l.module_entity_id = #{inputDto.moduleEntityId}


        AND l.attachment_group = #{inputDto.attachmentGroup}


        AND l.operation_type IN

            #{item}



        AND l.operation_result = #{inputDto.operationResult}


        AND l.client_ip = #{inputDto.clientIp}


        AND l.trace_id = #{inputDto.traceId}


        AND l.platform = #{inputDto.platform}


        AND l.create_time >= #{inputDto.createStartTime}


        AND l.create_time  <=  #{inputDto.createEndTime}


ORDER BY l.create_time DESC
